algorithm CountAboveAverage
    dimension data[3, 3] as integer;
    define row as integer;
    define column as integer;
    define total as integer;
    define average as real;
    define counter as integer;
    for row <- 0 to 2 step 1 do
        for column <- 0 to 2 step 1 do
            read data[row, column];
        endFor
    endFor
    total <- 0;
    for row <- 0 to 2 step 1 do
        for column <- 0 to 2 step 1 do
            total <- total + data[row, column];
        endFor
    endFor
    average <- total / 9;
    counter <- 0;
    for row <- 0 to 2 step 1 do
        for column <- 0 to 2 step 1 do
            if data[row, column] > average then
                counter <- counter + 1;
            endIf
        endFor
    endFor
    write counter;
endAlgorithm
